-- PHASE 4 REHEARSAL (generated from supabase/rehearsal/rehearsal_phase4.template.sql + the two migrations by scripts/build-rehearsal.mjs; do not edit this file by hand).
-- ONE batch that applies 20261128090000_freeze_enforcement.sql and 20261128100000_own_claims_rpc.sql (phase 2, 20261126090000, is already live), exercises them on the private
-- test trip, then ENDS WITH AN ERROR so that EVERYTHING ROLLS BACK. The result is the final error message: "REHEARSAL PASS [...]" or "REHEARSAL FAIL [...]".
-- Impersonation is claims-only plus SET LOCAL ROLE authenticated (the technique that passed on live); the service role is claims only, never SET ROLE service_role.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

CREATE TEMP TABLE _rehearsal (step text, ok boolean, detail text);
CREATE TEMP TABLE _rh_ctx (k text PRIMARY KEY, v text);
CREATE FUNCTION pg_temp.rh_rec(p_step text, p_ok boolean, p_detail text) RETURNS void LANGUAGE sql AS $f$
  INSERT INTO _rehearsal VALUES (p_step, coalesce(p_ok, false), left(p_detail, 400))
$f$;
CREATE FUNCTION pg_temp.rh_ctx(p_k text) RETURNS text LANGUAGE sql STABLE AS $f$
  SELECT v FROM _rh_ctx WHERE k = p_k
$f$;
CREATE FUNCTION pg_temp.rh_jwt(p_uid uuid) RETURNS void LANGUAGE plpgsql AS $f$
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', p_uid, 'role', 'authenticated')::text, true);
  PERFORM set_config('request.jwt.claim.sub', p_uid::text, true);
  PERFORM set_config('request.jwt.claim.role', 'authenticated', true);
END
$f$;
CREATE FUNCTION pg_temp.rh_svc() RETURNS void LANGUAGE plpgsql AS $f$
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('role', 'service_role')::text, true);
  PERFORM set_config('request.jwt.claim.sub', '', true);
  PERFORM set_config('request.jwt.claim.role', 'service_role', true);
END
$f$;
-- a PostgREST request header, as the API sets it
CREATE FUNCTION pg_temp.rh_header(p_build text) RETURNS void LANGUAGE plpgsql AS $f$
BEGIN
  PERFORM set_config('request.headers', json_build_object('x-client-info', p_build)::text, true);
END
$f$;

-- a real expense_splits row, whatever NOT NULL columns the live table has (filled by data type)
CREATE FUNCTION pg_temp.rh_make_split(p_e uuid, p_u uuid) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE
  c record; j jsonb := jsonb_build_object('id', gen_random_uuid(), 'expense_id', p_e, 'user_id', p_u, 'amount', 1);
BEGIN
  FOR c IN SELECT column_name, data_type, udt_name FROM information_schema.columns
           WHERE table_schema = 'public' AND table_name = 'expense_splits' AND is_nullable = 'NO' AND column_default IS NULL LOOP
    IF j ? c.column_name THEN CONTINUE; END IF;
    j := j || jsonb_build_object(c.column_name, CASE c.data_type
      WHEN 'uuid' THEN to_jsonb(gen_random_uuid()) WHEN 'numeric' THEN to_jsonb(0) WHEN 'integer' THEN to_jsonb(0) WHEN 'boolean' THEN to_jsonb(false)
      WHEN 'text' THEN to_jsonb('x'::text) WHEN 'timestamp with time zone' THEN to_jsonb(now())
      WHEN 'USER-DEFINED' THEN to_jsonb((SELECT e.enumlabel FROM pg_enum e JOIN pg_type t ON t.oid = e.enumtypid WHERE t.typname = c.udt_name ORDER BY e.enumsortorder LIMIT 1))
      ELSE to_jsonb('x'::text) END);
  END LOOP;
  INSERT INTO public.expense_splits SELECT (jsonb_populate_record(NULL::public.expense_splits, j)).*;
END
$f$;

-- ===== 0a. BEFORE the migrations: what is live is what the earlier migrations shipped; the new names are free ==============================================
DO $rh$
DECLARE
  v_o text; v_r text; v_n integer;
BEGIN
  BEGIN
    SELECT md5(prosrc) INTO v_o FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND proname = 'guard_claim_overclaim';
    SELECT md5(prosrc) INTO v_r FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND proname = '_receipt_resplit_table_items';
    PERFORM pg_temp.rh_rec('pre.bodies', v_o = '57312c8bff6c4ee090181819a3889626' AND v_r = 'ede35228aa5739454e3051eeaa24412e', format('guard_claim_overclaim md5=%s (want 57312c8bff6c4ee090181819a3889626) _receipt_resplit_table_items md5=%s (want ede35228aa5739454e3051eeaa24412e)', v_o, v_r));
    SELECT count(*) INTO v_n FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND proname IN ('_trip_frozen_for_write', '_expense_frozen_for_write', 'guard_frozen_expense', 'guard_frozen_expense_child', 'guard_trip_settlement_columns', 'set_my_receipt_claims', '_log_client_direct_write', 'count_client_direct_write');
    PERFORM pg_temp.rh_rec('pre.names_free', v_n = 0 AND to_regclass('public.client_direct_writes') IS NULL
      AND NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname IN ('trg_guard_frozen_expense', 'trg_guard_frozen_split', 'trg_guard_frozen_line', 'trg_guard_frozen_claim_delete', 'trg_guard_trip_settlement_columns', 'trg_count_direct_claims', 'trg_count_direct_lines', 'trg_count_direct_splits')),
      'none of the phase-4 functions, triggers or the counter table exist yet');
    INSERT INTO _rh_ctx VALUES ('act0', (SELECT count(*) FROM public.activity_feed)::text), ('notif0', (SELECT count(*) FROM public.notifications)::text);
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('pre', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== BEGIN MIGRATION 1 (verbatim copy of supabase/migrations/20261128090000_freeze_enforcement.sql) =====
SET LOCAL lock_timeout = '5s';

-- Phase 4, M1: a FROZEN trip (trips.settlement_snapshot IS NOT NULL) is enforced by the database, not only by the screens.
-- Until now "balances are frozen" was a UI rule plus a few guards (claims INSERT/UPDATE, the receipt RPCs). A stale page, an old cached client or a direct API call could
-- still add / change / delete expenses, splits and line items, delete a person's claims (the old claim page deletes first and inserts second, so a refused insert LOST the
-- claims) and write the freeze snapshot itself.
--
-- ADDITIVE AND RE-RUNNABLE: CREATE OR REPLACE for the new functions, DROP TRIGGER IF EXISTS + CREATE TRIGGER for the new triggers, DROP POLICY IF EXISTS, idempotent REVOKE/GRANT.
-- No existing function body is changed (guard_claim_overclaim stays byte-identical). The front end needs nothing from this: every refusal is a plain P0001 with a hint.
--
-- WHO IS A "CLIENT": current_user IN ('authenticated', 'anon') (the test every existing guard uses). NOT clients, therefore never blocked here: SECURITY DEFINER functions (they run
-- as the owner: freeze_settlements, unfreeze_settlements, remove_duplicate_settlement, the receipt RPCs, reitemize_expense ...), the service role (jobs, edge functions, payment
-- tokens) and foreign-key cascades (deleting a trip / expense / user cascades as the table owner).
--
-- WHAT A CLIENT CANNOT DO WHILE FROZEN (hint frozen, P0001):
--   expenses            INSERT, DELETE; UPDATE of anything outside the cosmetic whitelist W below
--   expense_splits      INSERT, UPDATE, DELETE
--   expense_line_items  INSERT, UPDATE, DELETE
--   expense_item_claims DELETE (INSERT / UPDATE were already refused by guard_claim_overclaim)
-- and, frozen or not (hint use_rpc, P0001): write trips.settlement_snapshot / settlement_snapshot_at / settlement_snapshot_by (freeze_settlements / unfreeze_settlements are the
-- only writers; on INSERT the three columns are forced NULL).
-- COSMETIC WHITELIST W (changes to these never move money and stay allowed on a frozen trip): description, category, vendor_name, location, receipt_url, receipt_date,
-- payment_date, place_id, option_id, booking_id, ai_parsed_data, parsing_error, updated_at (updated_at because set_updated_at fires first). A WHITELIST: any money column added later
-- is refused by default. Compared as to_jsonb(NEW) - W IS DISTINCT FROM to_jsonb(OLD) - W.
-- Settlements get NO new refusal (status updates, payment links and tokens are the point of freezing).
--
-- RESPONSES: direct client writes to expense_claim_responses are no longer possible (the three write policies are dropped and INSERT/UPDATE/DELETE are revoked from authenticated):
-- answers go through respond_to_receipt (20261126090000), which takes the locks in the standard order. The live client (HEAD 43c4b33) only SELECTs this table.
--
-- LOCK ORDER (unchanged, documented in 20261126090000): (1) 'settlement_freeze:<trip>' advisory lock, (2) 'receipt_claims:<expense>' advisory lock, (3) rows. THE ROW TRIGGERS BELOW
-- TAKE NO ADVISORY LOCK: they run after the statement already holds its row lock, and an advisory lock taken now would invert the order against the definer RPCs (which hold the
-- advisory locks and then UPDATE expenses): a deadlock. Instead they read the trips row with FOR SHARE (_trip_frozen_for_write): freeze_settlements / unfreeze_settlements hold the
-- advisory lock and then the trips row lock and never take an expense-family row lock afterwards, so a client write that waits on the trips row simply waits for the freeze to commit,
-- re-reads and is refused. A client write that got there first delays a freeze by milliseconds. KNOWN, ACCEPTED: deleting a whole trip (holds the trips row, cascades into
-- expenses) at the same instant as a client expense write can be aborted by the deadlock detector on one side (40P01); the CI concurrency test records it.
--
-- OLD CACHED CLIENTS (what they see): add / edit / delete expense -> "Balances are frozen ..." as the failure text, nothing written; the old claim page's save now stops at its first
-- request (the DELETE), so nothing is lost; booking "log expense" leaves a booking without an expense (harmless, the new client hides it while frozen).

-- ---------------------------------------------------------------------------------------------------------------------
-- Helper: is this trip frozen? (reads the trips row FOR SHARE; definer because participants cannot lock trips rows under RLS)
-- ---------------------------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public._trip_frozen_for_write(p_trip_id uuid)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_frozen boolean;
BEGIN
  SELECT t.settlement_snapshot IS NOT NULL INTO v_frozen FROM public.trips t WHERE t.id = p_trip_id FOR SHARE;
  RETURN coalesce(v_frozen, false);
END
$$;

-- Same, from an EXPENSE id: the lookup of expenses.trip_id runs as the owner, so an expense the client cannot see (RLS) can never make the guard skip the check.
CREATE OR REPLACE FUNCTION public._expense_frozen_for_write(p_expense_id uuid)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_trip uuid;
BEGIN
  SELECT e.trip_id INTO v_trip FROM public.expenses e WHERE e.id = p_expense_id;
  IF v_trip IS NULL THEN
    RETURN false;
  END IF;
  RETURN public._trip_frozen_for_write(v_trip);
END
$$;

-- ---------------------------------------------------------------------------------------------------------------------
-- expenses
-- ---------------------------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.guard_frozen_expense()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
DECLARE
  v_trip uuid;
  -- cosmetic whitelist (see the header)
  w text[] := ARRAY['description', 'category', 'vendor_name', 'location', 'receipt_url', 'receipt_date', 'payment_date', 'place_id', 'option_id',
                    'booking_id', 'ai_parsed_data', 'parsing_error', 'updated_at'];
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;
  v_trip := CASE WHEN TG_OP = 'INSERT' THEN NEW.trip_id ELSE OLD.trip_id END;
  IF NOT public._trip_frozen_for_write(v_trip) THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;
  IF TG_OP = 'UPDATE' AND (to_jsonb(NEW) - w) IS NOT DISTINCT FROM (to_jsonb(OLD) - w) THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'Balances are frozen while people settle up, so expenses can''t be added or changed. An organizer can unfreeze them in Settle up.'
    USING ERRCODE = 'P0001', HINT = 'frozen';
END
$$;
DROP TRIGGER IF EXISTS trg_guard_frozen_expense ON public.expenses;
CREATE TRIGGER trg_guard_frozen_expense BEFORE INSERT OR UPDATE OR DELETE ON public.expenses
  FOR EACH ROW EXECUTE FUNCTION public.guard_frozen_expense();

-- ---------------------------------------------------------------------------------------------------------------------
-- children of an expense: splits (all writes), line items (all writes), claims (DELETE)
-- ---------------------------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.guard_frozen_expense_child()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
DECLARE
  v_id uuid;
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;
  -- both sides of an UPDATE that moves a row to another expense
  FOREACH v_id IN ARRAY ARRAY[CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.expense_id END, CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE NEW.expense_id END] LOOP
    IF v_id IS NOT NULL THEN
      IF public._expense_frozen_for_write(v_id) THEN
        RAISE EXCEPTION 'Balances are frozen while people settle up, so expenses can''t be added or changed. An organizer can unfreeze them in Settle up.'
          USING ERRCODE = 'P0001', HINT = 'frozen';
      END IF;
    END IF;
  END LOOP;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;
DROP TRIGGER IF EXISTS trg_guard_frozen_split ON public.expense_splits;
CREATE TRIGGER trg_guard_frozen_split BEFORE INSERT OR UPDATE OR DELETE ON public.expense_splits
  FOR EACH ROW EXECUTE FUNCTION public.guard_frozen_expense_child();
DROP TRIGGER IF EXISTS trg_guard_frozen_line ON public.expense_line_items;
CREATE TRIGGER trg_guard_frozen_line BEFORE INSERT OR UPDATE OR DELETE ON public.expense_line_items
  FOR EACH ROW EXECUTE FUNCTION public.guard_frozen_expense_child();
DROP TRIGGER IF EXISTS trg_guard_frozen_claim_delete ON public.expense_item_claims;
CREATE TRIGGER trg_guard_frozen_claim_delete BEFORE DELETE ON public.expense_item_claims
  FOR EACH ROW EXECUTE FUNCTION public.guard_frozen_expense_child();

-- ---------------------------------------------------------------------------------------------------------------------
-- trips: the freeze snapshot is written only by freeze_settlements / unfreeze_settlements
-- ---------------------------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.guard_trip_settlement_columns()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
  IF current_user IN ('authenticated', 'anon') THEN
    IF TG_OP = 'INSERT' THEN
      NEW.settlement_snapshot := NULL;
      NEW.settlement_snapshot_at := NULL;
      NEW.settlement_snapshot_by := NULL;
    ELSIF NEW.settlement_snapshot IS DISTINCT FROM OLD.settlement_snapshot
          OR NEW.settlement_snapshot_at IS DISTINCT FROM OLD.settlement_snapshot_at
          OR NEW.settlement_snapshot_by IS DISTINCT FROM OLD.settlement_snapshot_by THEN
      RAISE EXCEPTION 'Freeze and unfreeze through Settle up (reload the app if this keeps happening).' USING ERRCODE = 'P0001', HINT = 'use_rpc';
    END IF;
  END IF;
  RETURN NEW;
END
$$;
DROP TRIGGER IF EXISTS trg_guard_trip_settlement_columns ON public.trips;
CREATE TRIGGER trg_guard_trip_settlement_columns BEFORE INSERT OR UPDATE ON public.trips
  FOR EACH ROW EXECUTE FUNCTION public.guard_trip_settlement_columns();

-- ---------------------------------------------------------------------------------------------------------------------
-- expense_claim_responses: writes only through respond_to_receipt (and the other definer functions)
-- ---------------------------------------------------------------------------------------------------------------------
DROP POLICY IF EXISTS "Users can add their own claim response" ON public.expense_claim_responses;
DROP POLICY IF EXISTS "Users can change their own claim response" ON public.expense_claim_responses;
DROP POLICY IF EXISTS "Users can delete their own claim response" ON public.expense_claim_responses;
REVOKE INSERT, UPDATE, DELETE ON public.expense_claim_responses FROM authenticated, anon;

-- ---------------------------------------------------------------------------------------------------------------------
-- Privileges
-- ---------------------------------------------------------------------------------------------------------------------
REVOKE ALL ON FUNCTION public._trip_frozen_for_write(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public._trip_frozen_for_write(uuid) TO authenticated, service_role;
REVOKE ALL ON FUNCTION public._expense_frozen_for_write(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public._expense_frozen_for_write(uuid) TO authenticated, service_role;
REVOKE ALL ON FUNCTION public.guard_frozen_expense() FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.guard_frozen_expense_child() FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.guard_trip_settlement_columns() FROM PUBLIC, anon, authenticated, service_role;

NOTIFY pgrst, 'reload schema';
-- ===== END MIGRATION 1 =====
-- ===== BEGIN MIGRATION 2 (verbatim copy of supabase/migrations/20261128100000_own_claims_rpc.sql) =====
SET LOCAL lock_timeout = '5s';

-- Phase 4, M2: the server computes the amounts of a person's OWN claims, and we count the direct writes that old clients still make.
--
-- ADDITIVE AND RE-RUNNABLE: CREATE TABLE IF NOT EXISTS, CREATE OR REPLACE, DROP TRIGGER IF EXISTS + CREATE TRIGGER, idempotent REVOKE/GRANT. The ONE existing function replaced is
-- _receipt_resplit_table_items (20261126090000): identical except that it writes an activity entry when someone's share of a TABLE item goes up (see below). Direct claim writes are NOT
-- refused (that is a later, evidence-gated migration); they are only counted.
--
-- set_my_receipt_claims(p_expense_id uuid, p_lines jsonb) -> jsonb       (authenticated)
--   p_lines = [{line_item_id, quantity}]: the caller's OWN quantity on each listed line (hundredths allowed, 0 = take myself off the line). The SERVER computes amount_owed with the
--   client's rule (claimMath.ts claimAmountMinor): the caller's share of the line total at the unit price, rounded half away from zero in minor units; when the claim takes the last of the
--   line it takes exactly what the other rows left, so a fully claimed line adds up to its total to the penny. Shared fixtures: scratchpad/phase4 parity cases (ownClaimParityCases.json).
--   _receipt_begin(p, false) does the auth, the locks (freeze lock then expense lock), frozen / closed / itemised / "tagged or payer or manager" checks. Leftover parts are stripped first and
--   re-shared afterwards (the 'same' mode, 'everyone' when the chosen person is gone), exactly like a link toggle. The caller's other rows and everyone else's own claims are never touched.
--   Refusals (P0001/22023/42501, hint): auth, not_found, forbidden, frozen, claims_closed, not_itemised, currency_unsupported, bad_input, bad_line, table_item (a table item is not claimed by
--   hand), fixed_share (the caller's row on that line is a shared / fractional share: use the share picker), overclaimed (more than is left).
--   Returns the same shape as set_receipt_claims (expense_id, currency, status, lines[], unclaimed_total, unclaimed_lines[], rows_written).
--
-- client_direct_writes: one row per STATEMENT that a signed-in CLIENT (role authenticated) ran directly against expense_item_claims, expense_line_items or expense_splits.
--   build = the X-Client-Info request header (PostgREST: current_setting('request.headers')); the app tags it 'trips-web/<sha>', old builds send 'supabase-js-web/x.y' (read: old). FAIL-OPEN: a
--   missing / unreadable header logs build NULL, never an error, and a logging problem never blocks the write. RLS on, no policies (service role / owner read it). Append-only.
--   Readout: SELECT build, tbl, op, count(*), max(at) FROM client_direct_writes WHERE at > now() - interval '7 days' GROUP BY 1, 2, 3 ORDER BY 4 DESC;
--   Statements that match zero rows are logged too (an old tab that tried is exactly what we want to see). RPC writes run as the owner and are never logged. Drop the table in Phase 5.
--
-- TABLE-ITEM SHARE ACTIVITY (decision 3): when "I wasn't there" (or a list change) re-splits a table item and a person who already had a share now pays MORE of it, an activity_feed row
-- 'receipt_table_share_changed' {line_item_id, line, user_id, from, to, currency} is written (actor = whoever caused it, or NULL for the job). No email is sent for it; the result email at the
-- deadline carries the final amounts.

CREATE TABLE IF NOT EXISTS public.client_direct_writes (
  at timestamptz NOT NULL DEFAULT now(),
  tbl text NOT NULL,
  op text NOT NULL,
  build text NULL,
  user_id uuid NULL
);
CREATE INDEX IF NOT EXISTS client_direct_writes_at_idx ON public.client_direct_writes (at);
ALTER TABLE public.client_direct_writes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.client_direct_writes FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.client_direct_writes TO service_role;

CREATE OR REPLACE FUNCTION public._log_client_direct_write(p_tbl text, p_op text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_build text;
BEGIN
  -- ONLY the statement triggers may log: a signed-in user calling this function through /rpc (trigger depth 0) gets a silent no-op, so the log cannot be filled by hand.
  -- (The trigger function runs as the CLIENT, so the client role needs EXECUTE for the trigger's PERFORM to work; the depth test is what protects the table.)
  IF pg_trigger_depth() = 0 THEN
    RETURN;
  END IF;
  BEGIN
    v_build := nullif(btrim(coalesce((nullif(current_setting('request.headers', true), '')::json) ->> 'x-client-info', '')), '');
  EXCEPTION WHEN OTHERS THEN
    v_build := NULL;   -- fail open
  END;
  BEGIN
    INSERT INTO public.client_direct_writes (tbl, op, build, user_id) VALUES (p_tbl, p_op, left(v_build, 120), auth.uid());
  EXCEPTION WHEN OTHERS THEN
    NULL;   -- never block the write because the counter failed
  END;
END
$$;

CREATE OR REPLACE FUNCTION public.count_client_direct_write()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
  IF current_user = 'authenticated' THEN
    PERFORM public._log_client_direct_write(TG_TABLE_NAME, TG_OP);
  END IF;
  RETURN NULL;
END
$$;
DROP TRIGGER IF EXISTS trg_count_direct_claims ON public.expense_item_claims;
CREATE TRIGGER trg_count_direct_claims AFTER INSERT OR UPDATE OR DELETE ON public.expense_item_claims FOR EACH STATEMENT EXECUTE FUNCTION public.count_client_direct_write();
DROP TRIGGER IF EXISTS trg_count_direct_lines ON public.expense_line_items;
CREATE TRIGGER trg_count_direct_lines AFTER INSERT OR UPDATE OR DELETE ON public.expense_line_items FOR EACH STATEMENT EXECUTE FUNCTION public.count_client_direct_write();
DROP TRIGGER IF EXISTS trg_count_direct_splits ON public.expense_splits;
CREATE TRIGGER trg_count_direct_splits AFTER INSERT OR UPDATE OR DELETE ON public.expense_splits FOR EACH STATEMENT EXECUTE FUNCTION public.count_client_direct_write();

-- ---------------------------------------------------------------------------------------------------------------------
-- set_my_receipt_claims
-- ---------------------------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.set_my_receipt_claims(p_expense_id uuid, p_lines jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_exp public.expenses;
  v_pw numeric;
  v_digits integer;
  v_item jsonb;
  v_line uuid;
  v_q numeric;
  v_li public.expense_line_items;
  v_my public.expense_item_claims;
  v_seen uuid[] := ARRAY[]::uuid[];
  v_has_leftover boolean;
  v_others_q numeric;
  v_others_minor bigint;
  v_total_minor bigint;
  v_amt_minor bigint;
  v_rows integer := 0;
  v_status text;
  v_lines jsonb;
  v_unclaimed_lines jsonb;
  v_unclaimed_minor bigint;
BEGIN
  v_exp := public._receipt_begin(p_expense_id, false);
  v_pw := power(10::numeric, public.currency_exponent(v_exp.currency));
  v_digits := public.currency_exponent(v_exp.currency);
  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) > 500 THEN
    RAISE EXCEPTION 'Lines must be a list of at most 500 entries' USING ERRCODE = '22023', HINT = 'bad_input';
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.expense_item_claims cl WHERE cl.expense_id = p_expense_id AND (cl.leftover_quantity > 0 OR cl.leftover_amount > 0)) INTO v_has_leftover;
  IF v_has_leftover THEN
    PERFORM public._receipt_strip_leftovers(p_expense_id);   -- the amounts below are computed against OWN parts; the leftovers are rebuilt at the end
  END IF;

  FOR v_item IN SELECT e.value FROM jsonb_array_elements(p_lines) AS e(value) LOOP
    IF jsonb_typeof(v_item) <> 'object' OR NOT (v_item ? 'line_item_id') OR jsonb_typeof(v_item -> 'quantity') NOT IN ('number', 'string') THEN
      RAISE EXCEPTION 'Each entry needs a line_item_id and a quantity' USING ERRCODE = '22023', HINT = 'bad_input';
    END IF;
    BEGIN
      v_line := (v_item ->> 'line_item_id')::uuid;
      v_q := (v_item ->> 'quantity')::numeric;
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
      RAISE EXCEPTION 'A line id or quantity is not valid' USING ERRCODE = '22023', HINT = 'bad_input';
    END;
    IF v_line IS NULL OR v_line = ANY (v_seen) OR v_q < 0 OR v_q >= 100000 OR round(v_q, 2) <> v_q THEN
      RAISE EXCEPTION 'A line is listed twice, or a quantity is negative or has more than 2 decimals' USING ERRCODE = '22023', HINT = 'bad_input';
    END IF;
    v_seen := v_seen || v_line;
    SELECT li.* INTO v_li FROM public.expense_line_items li WHERE li.id = v_line AND li.expense_id = p_expense_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'A line doesn''t belong to this expense' USING ERRCODE = '22023', HINT = 'bad_line';
    END IF;
    IF v_li.shared_by_all THEN
      RAISE EXCEPTION 'This item is shared by everyone; it is not claimed by hand' USING ERRCODE = '42501', HINT = 'table_item';
    END IF;
    SELECT cl.* INTO v_my FROM public.expense_item_claims cl WHERE cl.line_item_id = v_line AND cl.user_id = v_uid;
    IF FOUND THEN
      IF round(v_q * 100) = round(v_my.quantity_claimed * 100) THEN
        CONTINUE;   -- nothing to change on this line
      END IF;
      IF v_my.source = 'shared' OR abs(v_my.quantity_claimed - round(v_my.quantity_claimed)) >= 0.005 THEN
        RAISE EXCEPTION 'Your part of this item is a shared or fractional share; change it with the share picker' USING ERRCODE = '42501', HINT = 'fixed_share';
      END IF;
    ELSIF v_q = 0 THEN
      CONTINUE;
    END IF;
    SELECT coalesce(sum(cl.quantity_claimed), 0), coalesce(sum(round(cl.amount_owed * v_pw)), 0)::bigint INTO v_others_q, v_others_minor
    FROM public.expense_item_claims cl WHERE cl.line_item_id = v_line AND cl.user_id <> v_uid;
    IF v_q > v_li.quantity - v_others_q + 0.011 THEN
      RAISE EXCEPTION 'There is not that much of this item left to claim' USING ERRCODE = 'P0001', HINT = 'overclaimed';
    END IF;
    IF v_q = 0 THEN
      DELETE FROM public.expense_item_claims WHERE line_item_id = v_line AND user_id = v_uid;
      v_rows := v_rows + 1;
      CONTINUE;
    END IF;
    v_total_minor := round(v_li.total_amount * v_pw)::bigint;
    IF v_li.quantity - v_others_q - v_q < 0.001 THEN
      v_amt_minor := greatest(0, v_total_minor - v_others_minor);   -- takes the last of the line: exactly what the others left
    ELSE
      v_amt_minor := round(v_total_minor::numeric / v_li.quantity * v_q)::bigint;
    END IF;
    IF v_my.id IS NOT NULL THEN
      UPDATE public.expense_item_claims SET quantity_claimed = v_q, amount_owed = v_amt_minor::numeric / v_pw WHERE id = v_my.id;
    ELSE
      INSERT INTO public.expense_item_claims (line_item_id, user_id, expense_id, quantity_claimed, amount_owed, source, created_by)
      VALUES (v_line, v_uid, p_expense_id, v_q, v_amt_minor::numeric / v_pw, 'self', v_uid);
    END IF;
    v_rows := v_rows + 1;
  END LOOP;

  -- leftovers were stripped: rebuild them the way they were shared (this also re-splits table items and refreshes the status)
  IF v_has_leftover AND v_exp.leftover_mode IS NOT NULL THEN
    PERFORM public._receipt_after_tagged_change(p_expense_id);
  END IF;
  v_status := public._receipt_refresh_status(p_expense_id);

  INSERT INTO public.activity_feed (trip_id, actor, verb, entity, metadata)
  VALUES (v_exp.trip_id, v_uid, 'receipt_claims_set', jsonb_build_object('type', 'expense', 'id', p_expense_id, 'label', v_exp.description),
          jsonb_build_object('self', true, 'rows', v_rows, 'lines', jsonb_array_length(p_lines)));

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'line_item_id', l.line_item_id, 'shared_by_all', li.shared_by_all,
           'total', round(l.total_minor::numeric / v_pw, v_digits), 'quantity', li.quantity,
           'claimed_total', round(l.claimed_minor::numeric / v_pw, v_digits), 'unclaimed', round(l.remaining_minor::numeric / v_pw, v_digits),
           'people', (SELECT coalesce(jsonb_agg(jsonb_build_object(
                         'user_id', cl.user_id, 'quantity', cl.quantity_claimed, 'amount', cl.amount_owed, 'source', cl.source,
                         'leftover_quantity', cl.leftover_quantity, 'leftover_amount', cl.leftover_amount) ORDER BY cl.user_id), '[]'::jsonb)
                      FROM public.expense_item_claims cl WHERE cl.line_item_id = l.line_item_id)
         ) ORDER BY l.line_number, l.line_item_id), '[]'::jsonb)
    INTO v_lines
  FROM public._receipt_lines(p_expense_id, true) l JOIN public.expense_line_items li ON li.id = l.line_item_id
  WHERE l.line_item_id = ANY (v_seen);
  SELECT coalesce(jsonb_agg(jsonb_build_object('line_item_id', l.line_item_id, 'unclaimed', round(l.remaining_minor::numeric / v_pw, v_digits)) ORDER BY l.line_number, l.line_item_id), '[]'::jsonb),
         coalesce(sum(l.remaining_minor), 0)
    INTO v_unclaimed_lines, v_unclaimed_minor
  FROM public._receipt_lines(p_expense_id, true) l WHERE l.remaining_minor > 0;

  RETURN jsonb_build_object('expense_id', p_expense_id, 'currency', v_exp.currency, 'status', v_status, 'lines', v_lines,
                            'unclaimed_total', round(v_unclaimed_minor::numeric / v_pw, v_digits), 'unclaimed_lines', v_unclaimed_lines, 'rows_written', v_rows);
END
$$;

-- ---------------------------------------------------------------------------------------------------------------------
-- table-item share activity (replaces the 20261126090000 body; the only difference is the activity entry)
-- ---------------------------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public._receipt_resplit_table_items(p_expense_id uuid)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_exp public.expenses;
  v_tagged uuid[];
  v_k integer;
  v_pw numeric;
  v_li public.expense_line_items;
  v_qs bigint[];
  v_as bigint[];
  v_prev jsonb;
  v_n integer := 0;
  v_old_skip text;
  v_exact boolean;
  v_prevamt jsonb;
  v_old numeric;
  i integer;
BEGIN
  SELECT * INTO v_exp FROM public.expenses WHERE id = p_expense_id;
  IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM public.expense_line_items l WHERE l.expense_id = p_expense_id AND l.shared_by_all) THEN
    RETURN 0;
  END IF;
  v_tagged := public._receipt_tagged(p_expense_id);
  v_k := coalesce(cardinality(v_tagged), 0);
  IF v_k = 0 THEN
    RETURN 0;
  END IF;
  v_pw := power(10::numeric, public.currency_exponent(v_exp.currency));
  v_old_skip := current_setting('receipt.skip_done_clear', true);
  PERFORM set_config('receipt.skip_done_clear', 'on', true);
  FOR v_li IN SELECT * FROM public.expense_line_items l WHERE l.expense_id = p_expense_id AND l.shared_by_all ORDER BY l.line_number LOOP
    IF v_k > round(v_li.quantity * 100) THEN
      CONTINUE;
    END IF;
    v_qs := public._receipt_even_split(round(v_li.quantity * 100)::bigint, v_k);
    v_as := public._receipt_even_split(round(v_li.total_amount * v_pw)::bigint, v_k);
    SELECT (SELECT count(*) FROM public.expense_item_claims c WHERE c.line_item_id = v_li.id) = v_k
           AND NOT EXISTS (SELECT 1 FROM unnest(v_tagged) WITH ORDINALITY AS u(uid, ord)
                           LEFT JOIN public.expense_item_claims c ON c.line_item_id = v_li.id AND c.user_id = u.uid
                           WHERE c.id IS NULL OR round(c.quantity_claimed * 100) <> v_qs[u.ord] OR round(c.amount_owed * v_pw) <> v_as[u.ord]
                              OR c.leftover_quantity <> 0 OR c.leftover_amount <> 0)
      INTO v_exact;
    IF v_exact THEN
      CONTINUE;
    END IF;
    SELECT coalesce(jsonb_object_agg(c.user_id::text, to_jsonb(coalesce(c.created_by, c.user_id))), '{}'::jsonb) INTO v_prev
    FROM public.expense_item_claims c WHERE c.line_item_id = v_li.id AND c.quantity_claimed - c.leftover_quantity > 0;
    SELECT coalesce(jsonb_object_agg(c.user_id::text, to_jsonb(c.amount_owed - c.leftover_amount)), '{}'::jsonb) INTO v_prevamt FROM public.expense_item_claims c WHERE c.line_item_id = v_li.id;
    DELETE FROM public.expense_item_claims WHERE line_item_id = v_li.id;
    FOR i IN 1..v_k LOOP
      INSERT INTO public.expense_item_claims (line_item_id, user_id, expense_id, quantity_claimed, amount_owed, source, created_by)
      VALUES (v_li.id, v_tagged[i], p_expense_id, v_qs[i]::numeric / 100, v_as[i]::numeric / v_pw, 'shared',
              CASE WHEN v_prev ? v_tagged[i]::text THEN (v_prev ->> v_tagged[i]::text)::uuid ELSE v_exp.paid_by END);
      -- a person who already had a share of this table item and now pays MORE of it (someone was removed / said "I wasn't there"): an activity entry, no email
      v_old := (v_prevamt ->> v_tagged[i]::text)::numeric;
      IF v_old IS NOT NULL AND v_as[i]::numeric / v_pw > v_old THEN
        INSERT INTO public.activity_feed (trip_id, actor, verb, entity, metadata)
        VALUES (v_exp.trip_id, auth.uid(), 'receipt_table_share_changed',
                jsonb_build_object('type', 'expense', 'id', p_expense_id, 'label', v_exp.description),
                jsonb_build_object('line_item_id', v_li.id, 'line', v_li.name_original, 'user_id', v_tagged[i], 'from', v_old, 'to', v_as[i]::numeric / v_pw,
                                   'currency', v_exp.currency));
      END IF;
    END LOOP;
    v_n := v_n + 1;
  END LOOP;
  PERFORM set_config('receipt.skip_done_clear', coalesce(v_old_skip, ''), true);
  RETURN v_n;
END
$$;

REVOKE ALL ON FUNCTION public._receipt_resplit_table_items(uuid) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public._log_client_direct_write(text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public._log_client_direct_write(text, text) TO authenticated, service_role;
REVOKE ALL ON FUNCTION public.count_client_direct_write() FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.set_my_receipt_claims(uuid, jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.set_my_receipt_claims(uuid, jsonb) TO authenticated;

NOTIFY pgrst, 'reload schema';
-- ===== END MIGRATION 2 =====

-- ===== 0. the test trip, the two people ==========================================================================================
DO $rh$
DECLARE
  v_trip constant uuid := 'be551bc4-a524-4b6a-a0c9-b74a7168ced4';
  v_a uuid; v_b uuid; v_name text; v_frozen boolean; v_n integer;
BEGIN
  BEGIN
    SELECT t.created_by, t.name, t.settlement_snapshot IS NOT NULL INTO v_a, v_name, v_frozen FROM public.trips t WHERE t.id = v_trip;
    IF NOT FOUND THEN
      PERFORM pg_temp.rh_rec('setup.trip', false, 'test trip be551bc4-... not found');
      RETURN;
    END IF;
    SELECT tp.user_id INTO v_b FROM public.trip_participants tp
     WHERE tp.trip_id = v_trip AND tp.user_id <> v_a AND coalesce(tp.active, true)
     ORDER BY public._settlement_can_manage(v_trip, tp.user_id), tp.user_id LIMIT 1;
    SELECT count(*) INTO v_n FROM public.trip_participants tp WHERE tp.trip_id = v_trip;
    INSERT INTO _rh_ctx VALUES ('trip', v_trip::text), ('a', v_a::text), ('b_manager', coalesce(public._settlement_can_manage(v_trip, v_b), false)::text);
    IF v_b IS NOT NULL THEN INSERT INTO _rh_ctx VALUES ('b', v_b::text); END IF;
    UPDATE public.trips SET settlement_snapshot = NULL WHERE id = v_trip;   -- as the OWNER (not a client): unfrozen for the first half; rolled back with everything
    PERFORM pg_temp.rh_rec('setup.trip', v_a IS NOT NULL AND v_b IS NOT NULL, format('name=%s participants=%s was_frozen=%s', v_name, v_n, v_frozen));
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('setup.trip', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== 1. structure ===========================================================================================================================
DO $rh$
DECLARE
  v_txt text; v_bad text := ''; r record;
BEGIN
  BEGIN
    SELECT string_agg(x.t || '.' || x.n, ',') INTO v_txt FROM (VALUES
      ('expenses', 'trg_guard_frozen_expense'), ('expense_splits', 'trg_guard_frozen_split'), ('expense_line_items', 'trg_guard_frozen_line'), ('expense_item_claims', 'trg_guard_frozen_claim_delete'),
      ('trips', 'trg_guard_trip_settlement_columns'), ('expense_item_claims', 'trg_count_direct_claims'), ('expense_line_items', 'trg_count_direct_lines'), ('expense_splits', 'trg_count_direct_splits')) x(t, n)
     WHERE NOT EXISTS (SELECT 1 FROM pg_trigger g WHERE g.tgrelid = ('public.' || x.t)::regclass AND g.tgname = x.n AND NOT g.tgisinternal AND g.tgenabled = 'O');
    PERFORM pg_temp.rh_rec('struct.triggers', v_txt IS NULL, coalesce('missing/disabled: ' || v_txt, '8 new triggers enabled'));
    PERFORM pg_temp.rh_rec('struct.response_policies', (SELECT array_agg(cmd ORDER BY cmd) FROM pg_policies WHERE tablename = 'expense_claim_responses') = ARRAY['SELECT']
      AND NOT has_table_privilege('authenticated', 'public.expense_claim_responses', 'INSERT'), 'only the SELECT policy is left; no INSERT privilege for authenticated');
    FOR r IN SELECT * FROM (VALUES
      ('public._trip_frozen_for_write(uuid)', false, true),
      ('public._expense_frozen_for_write(uuid)', false, true),
      ('public.set_my_receipt_claims(uuid,jsonb)', false, true),
      ('public._log_client_direct_write(text,text)', false, true),
      ('public.guard_frozen_expense()', false, false),
      ('public.guard_frozen_expense_child()', false, false),
      ('public.guard_trip_settlement_columns()', false, false),
      ('public.count_client_direct_write()', false, false),
      ('public._receipt_resplit_table_items(uuid)', false, false)
    ) AS x(f, want_anon, want_auth) LOOP
      IF has_function_privilege('anon', r.f, 'EXECUTE') IS DISTINCT FROM r.want_anon OR has_function_privilege('authenticated', r.f, 'EXECUTE') IS DISTINCT FROM r.want_auth THEN
        v_bad := v_bad || r.f || ' ';
      END IF;
    END LOOP;
    IF has_table_privilege('authenticated', 'public.client_direct_writes', 'SELECT') THEN v_bad := v_bad || 'client_direct_writes-readable '; END IF;
    PERFORM pg_temp.rh_rec('struct.privileges', v_bad = '', CASE WHEN v_bad = '' THEN '8 functions + the counter table: as intended' ELSE 'wrong: ' || v_bad END);
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('struct', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== 2. UNFROZEN: normal work, set_my_receipt_claims (server amounts), the direct-write counter ====================================================
DO $rh$
DECLARE
  v_trip uuid := pg_temp.rh_ctx('trip')::uuid; v_a uuid := pg_temp.rh_ctx('a')::uuid; v_b uuid := pg_temp.rh_ctx('b')::uuid;
  v_e uuid; v_l1 uuid; v_l2 uuid; v_x uuid; v_r jsonb; v_hint text; v_n integer; v_amt numeric; v_sum numeric;
BEGIN
  IF v_a IS NULL OR v_b IS NULL THEN PERFORM pg_temp.rh_rec('unfrozen', false, 'no test trip / people'); RETURN; END IF;
  BEGIN
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    INSERT INTO public.expenses (trip_id, paid_by, amount, currency, description, status, ai_parsed, participant_ids)
    VALUES (v_trip, v_a, 40.01, 'GBP', 'REHEARSAL phase 4 receipt (rolled back)', 'unallocated', true, ARRAY[v_a, v_b]) RETURNING id INTO v_e;
    INSERT INTO public.expense_line_items (expense_id, line_number, name_original, quantity, unit_price, subtotal, total_amount) VALUES (v_e, 1, 'beers x3', 3, 3.33, 10.01, 10.01) RETURNING id INTO v_l1;
    INSERT INTO public.expense_line_items (expense_id, line_number, name_original, quantity, unit_price, subtotal, total_amount) VALUES (v_e, 2, 'pizza', 1, 30, 30, 30) RETURNING id INTO v_l2;
    RESET ROLE;
    INSERT INTO _rh_ctx VALUES ('e', v_e::text), ('l1', v_l1::text), ('l2', v_l2::text);
    PERFORM pg_temp.rh_rec('unfrozen.client_can_create', true, 'GBP 40.01: beers 10.01 (3 units) + pizza 30.00');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('unfrozen.client_can_create', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
    RETURN;
  END;
  -- server-computed amounts: A, B and A again take the three beers; the last one takes what is left (3.35 | 3.33 | 3.33 = 10.01 or similar, exactly the line)
  BEGIN
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    v_r := public.set_my_receipt_claims(v_e, jsonb_build_array(jsonb_build_object('line_item_id', v_l1, 'quantity', 2)));
    RESET ROLE;
    PERFORM pg_temp.rh_jwt(v_b);
    SET LOCAL ROLE authenticated;
    v_r := public.set_my_receipt_claims(v_e, jsonb_build_array(jsonb_build_object('line_item_id', v_l1, 'quantity', 1)));
    RESET ROLE;
    SELECT sum(amount_owed), count(*) INTO v_sum, v_n FROM public.expense_item_claims WHERE line_item_id = v_l1;
    SELECT amount_owed INTO v_amt FROM public.expense_item_claims WHERE line_item_id = v_l1 AND user_id = v_a;
    PERFORM pg_temp.rh_rec('own_claims.server_amounts', v_sum = 10.01 AND v_n = 2 AND v_amt = 6.67 AND (v_r #>> '{lines,0,unclaimed}')::numeric = 0,
      format('line total 10.01 claimed %s over %s rows (A 2 units = %s, B takes the last unit); result unclaimed=%s', v_sum, v_n, v_amt, v_r #>> '{lines,0,unclaimed}'));
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('own_claims.server_amounts', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
  BEGIN
    PERFORM pg_temp.rh_jwt(v_b);
    SET LOCAL ROLE authenticated;
    PERFORM public.set_my_receipt_claims(v_e, jsonb_build_array(jsonb_build_object('line_item_id', v_l1, 'quantity', 2)));
    RESET ROLE;
    PERFORM pg_temp.rh_rec('own_claims.overclaim_refused', false, 'NOT refused');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    PERFORM pg_temp.rh_rec('own_claims.overclaim_refused', v_hint = 'overclaimed', SQLSTATE || ' hint=' || coalesce(v_hint, ''));
  END;
  -- the counter: a DIRECT client write (an old build) is logged with its build tag; an RPC write is not
  BEGIN
    DELETE FROM public.client_direct_writes;
    PERFORM pg_temp.rh_header('supabase-js-web/2.78.0');
    PERFORM pg_temp.rh_jwt(v_b);
    SET LOCAL ROLE authenticated;
    INSERT INTO public.expense_item_claims (line_item_id, user_id, expense_id, quantity_claimed, amount_owed) VALUES (v_l2, v_b, v_e, 1, 30);
    PERFORM public.set_my_receipt_claims(v_e, jsonb_build_array(jsonb_build_object('line_item_id', v_l2, 'quantity', 0)));
    RESET ROLE;
    SELECT count(*) INTO v_n FROM public.client_direct_writes WHERE tbl = 'expense_item_claims' AND op = 'INSERT' AND build = 'supabase-js-web/2.78.0' AND user_id = v_b;
    PERFORM pg_temp.rh_rec('counter.direct_write_logged_rpc_not', v_n = 1 AND (SELECT count(*) FROM public.client_direct_writes) = 1, format('direct INSERT rows with the build tag: %s; total log rows: %s (the RPC write is not logged)', v_n, (SELECT count(*) FROM public.client_direct_writes)));
    PERFORM set_config('request.headers', '', true);
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('counter.direct_write_logged_rpc_not', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== 3. FROZEN: refusals, then what stays allowed ==========================================================================================
DO $rh$
DECLARE
  v_trip uuid := pg_temp.rh_ctx('trip')::uuid; v_a uuid := pg_temp.rh_ctx('a')::uuid; v_b uuid := pg_temp.rh_ctx('b')::uuid; v_e uuid := pg_temp.rh_ctx('e')::uuid;
  v_l1 uuid := pg_temp.rh_ctx('l1')::uuid; v_hint text; v_n integer; v_before integer; v_sp integer;
  v_cases text[][] := ARRAY[
    ['expense INSERT', 'b', 'INSERT INTO public.expenses (trip_id, paid_by, amount, description) VALUES (''%trip%'', ''%b%'', 5, ''x'')'],
    ['amount UPDATE', 'a', 'UPDATE public.expenses SET amount = amount + 1 WHERE id = ''%e%'''],
    ['paid_by UPDATE', 'a', 'UPDATE public.expenses SET paid_by = ''%b%'' WHERE id = ''%e%'''],
    ['expense DELETE', 'a', 'DELETE FROM public.expenses WHERE id = ''%e%'''],
    ['splits INSERT', 'a', 'INSERT INTO public.expense_splits (expense_id, user_id, amount) VALUES (''%e%'', ''%b%'', 1)'],
    ['line item INSERT', 'a', 'INSERT INTO public.expense_line_items (expense_id, line_number, name_original, quantity, unit_price, subtotal, total_amount) VALUES (''%e%'', 9, ''x'', 1, 1, 1, 1)'],
    ['line item DELETE', 'a', 'DELETE FROM public.expense_line_items WHERE id = ''%l1%'''],
    ['claim DELETE', 'b', 'DELETE FROM public.expense_item_claims WHERE expense_id = ''%e%'' AND user_id = ''%b%'''],
    ['claim INSERT', 'b', 'INSERT INTO public.expense_item_claims (line_item_id, user_id, expense_id, quantity_claimed, amount_owed) VALUES (''%l1%'', ''%b%'', ''%e%'', 0.01, 0.01)']
  ];
  v_i integer; v_sql text; v_who uuid; v_s uuid;
BEGIN
  IF v_e IS NULL THEN PERFORM pg_temp.rh_rec('frozen', false, 'no test expense'); RETURN; END IF;
  UPDATE public.trips SET settlement_snapshot = jsonb_build_object('transactions', '[]'::jsonb) WHERE id = v_trip;     -- as the owner: freezes the test trip inside the transaction
  SELECT count(*) INTO v_before FROM public.expense_item_claims WHERE expense_id = v_e;
  FOR v_i IN 1..array_length(v_cases, 1) LOOP
    v_sql := replace(replace(replace(replace(v_cases[v_i][3], '%trip%', v_trip::text), '%b%', v_b::text), '%e%', v_e::text), '%l1%', v_l1::text);
    v_who := CASE v_cases[v_i][2] WHEN 'a' THEN v_a ELSE v_b END;
    BEGIN
      PERFORM pg_temp.rh_jwt(v_who);
      SET LOCAL ROLE authenticated;
      EXECUTE v_sql;
      RESET ROLE;
      PERFORM pg_temp.rh_rec('frozen.refused: ' || v_cases[v_i][1], false, 'NOT refused');
    EXCEPTION WHEN OTHERS THEN
      RESET ROLE;
      GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
      PERFORM pg_temp.rh_rec('frozen.refused: ' || v_cases[v_i][1], v_hint = 'frozen', SQLSTATE || ' hint=' || coalesce(v_hint, '') || ' ' || left(SQLERRM, 80));
    END;
  END LOOP;
  SELECT count(*) INTO v_n FROM public.expense_item_claims WHERE expense_id = v_e;
  PERFORM pg_temp.rh_rec('frozen.nothing_lost', v_n = v_before AND (SELECT count(*) FROM public.expense_line_items WHERE expense_id = v_e) = 2, format('claims before %s after %s; lines still 2 (the old claim page''s delete-then-insert stops at the delete)', v_before, v_n));
  -- splits UPDATE / DELETE need a real row: create one (owner, trip unfrozen for that instant), then freeze again
  BEGIN
    UPDATE public.trips SET settlement_snapshot = NULL WHERE id = v_trip;
    PERFORM pg_temp.rh_make_split(v_e, v_b);
    UPDATE public.trips SET settlement_snapshot = jsonb_build_object('transactions', '[]'::jsonb) WHERE id = v_trip;
    SELECT count(*) INTO v_sp FROM public.expense_splits WHERE expense_id = v_e;
    PERFORM pg_temp.rh_rec('frozen.setup_split_row', v_sp = 1, 'split rows created: ' || v_sp);
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('frozen.setup_split_row', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
  FOR v_i IN 1..2 LOOP
    BEGIN
      PERFORM pg_temp.rh_jwt(v_a);
      SET LOCAL ROLE authenticated;
      IF v_i = 1 THEN
        UPDATE public.expense_splits SET amount = amount + 1 WHERE expense_id = v_e;
      ELSE
        DELETE FROM public.expense_splits WHERE expense_id = v_e;
      END IF;
      GET DIAGNOSTICS v_n = ROW_COUNT;
      RESET ROLE;
      PERFORM pg_temp.rh_rec('frozen.refused: splits ' || CASE v_i WHEN 1 THEN 'UPDATE' ELSE 'DELETE' END, false, 'NOT refused (rows=' || v_n || ')');
    EXCEPTION WHEN OTHERS THEN
      RESET ROLE;
      GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
      PERFORM pg_temp.rh_rec('frozen.refused: splits ' || CASE v_i WHEN 1 THEN 'UPDATE' ELSE 'DELETE' END, v_hint = 'frozen', SQLSTATE || ' hint=' || coalesce(v_hint, ''));
    END;
  END LOOP;
  -- the receipt RPCs
  BEGIN
    PERFORM pg_temp.rh_jwt(v_b);
    SET LOCAL ROLE authenticated;
    PERFORM public.set_my_receipt_claims(v_e, jsonb_build_array(jsonb_build_object('line_item_id', v_l1, 'quantity', 0)));
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.refused: set_my_receipt_claims', false, 'NOT refused');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    PERFORM pg_temp.rh_rec('frozen.refused: set_my_receipt_claims', v_hint = 'frozen', SQLSTATE || ' hint=' || coalesce(v_hint, ''));
  END;
  BEGIN
    PERFORM pg_temp.rh_jwt(v_b);
    SET LOCAL ROLE authenticated;
    INSERT INTO public.expense_claim_responses (expense_id, user_id, response) VALUES (v_e, v_b, 'done');
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.response_direct_write_gone', false, 'NOT refused');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.response_direct_write_gone', SQLSTATE = '42501', SQLSTATE || ' ' || left(SQLERRM, 80));
  END;
  -- allowed while frozen: cosmetic edits
  BEGIN
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    UPDATE public.expenses SET description = 'REHEARSAL renamed while frozen', receipt_url = 'rehearsal.jpg' WHERE id = v_e;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.allowed: cosmetic edit', v_n = 1 AND (SELECT description FROM public.expenses WHERE id = v_e) = 'REHEARSAL renamed while frozen', 'rows=' || v_n);
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.allowed: cosmetic edit', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
  -- the snapshot is written only by the RPCs
  BEGIN
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    UPDATE public.trips SET settlement_snapshot = NULL WHERE id = v_trip;
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.trips_snapshot_use_rpc', false, 'NOT refused');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    PERFORM pg_temp.rh_rec('frozen.trips_snapshot_use_rpc', v_hint = 'use_rpc', SQLSTATE || ' hint=' || coalesce(v_hint, ''));
  END;
  -- the service key and the definer RPCs are not clients
  BEGIN
    PERFORM pg_temp.rh_svc();
    UPDATE public.expenses SET amount = amount WHERE id = v_e;
    PERFORM pg_temp.rh_rec('frozen.allowed: service role write', true, 'ok');
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('frozen.allowed: service role write', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
  -- settlements while frozen: the payer marks one paid, the receiver confirms it (created by the organiser, as the freeze would)
  BEGIN
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    INSERT INTO public.settlements (trip_id, from_user_id, to_user_id, amount, currency, status, created_by, settled_at) VALUES (v_trip, v_b, v_a, 1.00, 'GBP', 'suggested', v_a, now()) RETURNING id INTO v_s;
    RESET ROLE;
    PERFORM pg_temp.rh_jwt(v_b);
    SET LOCAL ROLE authenticated;
    UPDATE public.settlements SET status = 'marked_paid' WHERE id = v_s;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.allowed: mark a payment paid', v_n = 1 AND (SELECT status FROM public.settlements WHERE id = v_s) = 'marked_paid', 'rows=' || v_n);
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    UPDATE public.settlements SET status = 'confirmed' WHERE id = v_s;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.allowed: confirm a payment', v_n = 1 AND (SELECT status FROM public.settlements WHERE id = v_s) = 'confirmed', 'rows=' || v_n);
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.allowed: mark / confirm a payment', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
  -- unfreeze by the organiser (the real RPC), and money edits work again
  BEGIN
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    PERFORM public.unfreeze_settlements(v_trip);
    UPDATE public.expenses SET amount = amount WHERE id = v_e;
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.allowed: unfreeze', (SELECT settlement_snapshot IS NULL FROM public.trips WHERE id = v_trip), 'unfreeze_settlements by the organiser works; the expense is editable again');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.allowed: unfreeze', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== 4. a throwaway FROZEN trip is deleted by its creator: the cascades run as the owner, through every guard ======================================
DO $rh$
DECLARE
  v_trip uuid := pg_temp.rh_ctx('trip')::uuid; v_a uuid := pg_temp.rh_ctx('a')::uuid; v_bb uuid := pg_temp.rh_ctx('b')::uuid; v_new uuid := gen_random_uuid(); v_x uuid; v_n integer;
BEGIN
  BEGIN
    INSERT INTO public.trips SELECT (jsonb_populate_record(NULL::public.trips, to_jsonb(t) || jsonb_build_object('id', v_new, 'name', 'REHEARSAL throwaway (rolled back)'))).* FROM public.trips t WHERE t.id = v_trip;
    INSERT INTO public.expenses (trip_id, paid_by, amount, currency, description) VALUES (v_new, v_a, 5, 'GBP', 'REHEARSAL throwaway expense') RETURNING id INTO v_x;
    UPDATE public.trips SET settlement_snapshot = jsonb_build_object('transactions', '[]'::jsonb) WHERE id = v_new;
    -- removing a participant on the frozen throwaway trip (the creator is its organiser): copy the two participant rows, then delete B's as the organiser
    INSERT INTO public.trip_participants SELECT (jsonb_populate_record(NULL::public.trip_participants, to_jsonb(p) || jsonb_build_object('trip_id', v_new))).* FROM public.trip_participants p WHERE p.trip_id = v_trip AND p.user_id IN (v_a, v_bb);
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    DELETE FROM public.trip_participants WHERE trip_id = v_new AND user_id = v_bb;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.allowed: remove a participant', v_n = 1, 'participant rows removed by the organiser: ' || v_n);
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    DELETE FROM public.trips WHERE id = v_new;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.trip_delete_cascades', v_n = 1 AND NOT EXISTS (SELECT 1 FROM public.expenses WHERE id = v_x), format('trip rows deleted=%s, its expense gone=%s (if 0 rows: the trips DELETE policy does not let the creator in; then only the cascade check is skipped)', v_n, NOT EXISTS (SELECT 1 FROM public.expenses WHERE id = v_x)));
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.trip_delete_cascades', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== 5. table-item share activity: "I wasn't there" moves the bread, A's share goes up, an activity row, no notification =========================
DO $rh$
DECLARE
  v_trip uuid := pg_temp.rh_ctx('trip')::uuid; v_a uuid := pg_temp.rh_ctx('a')::uuid; v_b uuid := pg_temp.rh_ctx('b')::uuid; v_e uuid; v_l uuid; v_l2 uuid; v_n integer;
BEGIN
  IF v_a IS NULL OR v_b IS NULL THEN RETURN; END IF;
  BEGIN
    INSERT INTO public.expenses (trip_id, paid_by, amount, currency, description, status, ai_parsed, participant_ids)
    VALUES (v_trip, v_a, 30.00, 'GBP', 'REHEARSAL table activity (rolled back)', 'unallocated', true, ARRAY[v_a, v_b]) RETURNING id INTO v_e;
    INSERT INTO public.expense_line_items (expense_id, line_number, name_original, quantity, unit_price, subtotal, total_amount) VALUES (v_e, 1, 'bread', 1, 9, 9, 9) RETURNING id INTO v_l;
    INSERT INTO public.expense_line_items (expense_id, line_number, name_original, quantity, unit_price, subtotal, total_amount) VALUES (v_e, 2, 'main', 1, 21, 21, 21) RETURNING id INTO v_l2;
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    PERFORM public.set_receipt_claims(v_e, jsonb_build_array(jsonb_build_object('line_item_id', v_l, 'shared_by_all', true), jsonb_build_object('line_item_id', v_l2, 'user_ids', jsonb_build_array(v_a))));
    RESET ROLE;
    PERFORM pg_temp.rh_jwt(v_b);
    SET LOCAL ROLE authenticated;
    PERFORM public.respond_to_receipt(v_e, 'not_there');
    RESET ROLE;
    SELECT count(*) INTO v_n FROM public.activity_feed WHERE verb = 'receipt_table_share_changed' AND entity ->> 'id' = v_e::text AND metadata ->> 'user_id' = v_a::text
      AND (metadata ->> 'from')::numeric = 4.50 AND (metadata ->> 'to')::numeric = 9.00;
    PERFORM pg_temp.rh_rec('activity.table_share_went_up', v_n = 1 AND (SELECT count(*) FROM public.notifications) = pg_temp.rh_ctx('notif0')::integer,
      format('activity rows for A (4.50 -> 9.00): %s; notifications unchanged', v_n));
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('activity.table_share_went_up', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== FINAL: report through the error message (this also rolls everything back) ===============================================================================
DO $rh$
DECLARE
  v_all boolean; v_json text; v_failed integer; v_total integer;
BEGIN
  SELECT coalesce(bool_and(ok), false), count(*) FILTER (WHERE NOT ok), count(*) INTO v_all, v_failed, v_total FROM _rehearsal;
  SELECT coalesce(jsonb_agg(jsonb_build_object('step', step, 'ok', ok, 'detail', left(detail, 160)) ORDER BY ok, ctid), '[]'::jsonb)::text INTO v_json FROM _rehearsal;
  IF length(v_json) > 6000 THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('step', step, 'ok', ok, 'detail', left(detail, CASE WHEN ok THEN 0 ELSE 90 END)) ORDER BY ok, ctid), '[]'::jsonb)::text INTO v_json FROM _rehearsal;
  END IF;
  IF length(v_json) > 6000 THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('step', step, 'ok', ok, 'detail', left(detail, 90)) ORDER BY ok, ctid), '[]'::jsonb)::text INTO v_json FROM _rehearsal WHERE NOT ok;
    v_json := left(v_json, 5800) || ' (only failing steps shown)';
  END IF;
  RAISE EXCEPTION '%', 'REHEARSAL ' || CASE WHEN v_all THEN 'PASS' ELSE 'FAIL' END || ' (' || v_total || ' steps, ' || v_failed || ' failed) ' || v_json;
END
$rh$;
ROLLBACK;
